package io.vaultbridge.app;
import java.io.*;
import org.json.*;

public final class SettingsFeedbackTest {
    static int passed;
    interface Attempt {void run()throws Exception;}
    static void check(boolean value,String label){if(!value)throw new AssertionError(label);passed++;}
    static void fails(Attempt action,String label)throws Exception{try{action.run();throw new AssertionError(label);}catch(IOException expected){passed++;}}
    public static void main(String[] args)throws Exception{
        AppearanceConfig vault=AppearanceConfig.parse("{\"theme\":\"obsidian\",\"accentColor\":\"#7f6df2\"}",false);
        check(AppearancePreferences.resolve(vault,false,"obsidian","obsidian","#d9b55c").dark,"legacy vault depth preserved");
        check(!AppearancePreferences.resolve(vault,true,"light","obsidian","#d9b55c").dark,"manual light overrides vault and system");
        check(AppearancePreferences.resolve(vault,false,"dark","custom","#d9b55c").dark,"manual dark overrides light system");
        check(!AppearancePreferences.resolve(vault,false,"system","custom","#d9b55c").dark,"system light independent of vault");
        check(AppearancePreferences.resolve(vault,true,"system","custom","#d9b55c").dark,"system dark live resolution");
        check(AppearancePreferences.resolve(vault,false,"light","obsidian","#d9b55c").accent==vault.accent,"vault color independent of manual depth");
        check(AppearancePreferences.resolve(vault,false,"obsidian","custom","#d9b55c").accent==0xffd9b55c,"custom color independent of vault depth");
        check(AppearancePreferences.resolve(vault,false,"obsidian","custom","broken").accent==vault.accent,"invalid saved custom color safe fallback");
        AppearanceConfig missing=AppearanceConfig.fallback(false,"no authorized vault");check(AppearancePreferences.resolve(missing,false,"dark","custom","#ffffff").dark,"vault failure retains manual depth");
        for(String color:new String[]{"#000000","#ffffff","#777777","#ffff00","#0000ff"}){UiTheme t=UiTheme.from(AppearancePreferences.resolve(vault,false,"dark","custom",color));check(UiTheme.contrast(t.accent,t.primaryInk)>=4.5,"button contrast "+color);}
        fails(()->FeedbackClient.endpoint(""),"unconfigured feedback fails closed");fails(()->FeedbackClient.endpoint("http://example.com/wp-json/vaultbridge-feedback/v1"),"clear text rejected");fails(()->FeedbackClient.endpoint("https://user:password@example.com/wp-json/vaultbridge-feedback/v1"),"embedded credentials rejected");fails(()->FeedbackClient.endpoint("https://example.com/wp-json/vaultbridge-feedback/v1?token=x"),"query rejected");fails(()->FeedbackClient.endpoint("https://example.com:8443/wp-json/vaultbridge-feedback/v1"),"unexpected port rejected");
        check(FeedbackClient.endpoint("https://example.com/wp-json/vaultbridge-feedback/v1").getPath().endsWith("/submit"),"endpoint exact submit path");
        String id="1234567890abcdef1234567890abcdef";JSONObject clean=FeedbackClient.payload(id,"suggestion","标题","正文","",false,"0.5.0","android");check(!clean.has("contact")&&!clean.has("contextOptional"),"optional fields absent by default");check(clean.keySet().equals(new java.util.HashSet<String>(java.util.Arrays.asList("schema","clientRequestId","type","title","body"))),"no implicit file or device fields");
        JSONObject opted=FeedbackClient.payload(id,"bug","标题","正文","作者填写",true,"0.5.0","android");check(opted.getJSONObject("contextOptional").length()==2,"context only version and platform");
        fails(()->FeedbackClient.payload(id,"suggestion"," ","正文","",false,"0.5.0","android"),"blank title refused");fails(()->FeedbackClient.payload(id,"suggestion","标题",new String(new char[3001]).replace('\0','x'),"",false,"0.5.0","android"),"oversize body refused");fails(()->FeedbackClient.payload("../path","suggestion","标题","正文","",false,"0.5.0","android"),"bad retry identity refused");
        JSONObject response=new JSONObject().put("ok",true).put("schema",1).put("clientRequestId",id).put("id","23").put("receipt","VB-23").put("receivedAt",1);
        check(FeedbackClient.receipt(201,response.toString(),id).equals("VB-23"),"durable new receipt accepted");check(FeedbackClient.receipt(200,response.toString(),id).equals("VB-23"),"retry receipt accepted");
        fails(()->FeedbackClient.receipt(201,response.toString(),"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),"wrong request receipt refused");fails(()->FeedbackClient.receipt(302,response.toString(),id),"redirect not success");fails(()->FeedbackClient.receipt(503,response.toString(),id),"pending not success");fails(()->FeedbackClient.receipt(200,"{}",id),"incomplete receipt refused");fails(()->FeedbackClient.receipt(200,"<html>ok</html>",id),"HTML not a receipt");response.put("receipt","VB-999");fails(()->FeedbackClient.receipt(201,response.toString(),id),"mismatched receipt refused");
        response.put("receipt","VB-23");response.put("ok","true");fails(()->FeedbackClient.receipt(201,response.toString(),id),"string boolean not receipt");response.put("ok",true).put("schema","1");fails(()->FeedbackClient.receipt(201,response.toString(),id),"string schema not receipt");response.put("schema",1).put("receivedAt","1");fails(()->FeedbackClient.receipt(201,response.toString(),id),"string timestamp not receipt");response.put("receivedAt",1).put("id",23);fails(()->FeedbackClient.receipt(201,response.toString(),id),"numeric identifier not canonical receipt");response.put("id","9999999999999999999").put("receipt","VB-9999999999999999999");fails(()->FeedbackClient.receipt(201,response.toString(),id),"overflow identifier not receipt");
        java.io.File archive=new java.io.File(args.length>0?args[0]:"work/feedback-test-"+java.util.UUID.randomUUID(),"feedback-archive");JSONObject first=FeedbackClient.payload(id,"suggestion","first","uncertain body","",false,"0.5.0","android");FeedbackDraftStore.preserve(archive,first);FeedbackDraftStore.preserve(archive,first);check(new java.io.File(archive,id+".json").exists(),"same draft retry retains original snapshot");JSONObject revised=FeedbackClient.payload("bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","bug","second","changed body","",false,"0.5.0","android");FeedbackDraftStore.preserve(archive,revised);check(archive.listFiles((dir,name)->name.endsWith(".json")).length==2,"editing draft preserves prior uncertain request");first.put("body","mutated same id");fails(()->FeedbackDraftStore.preserve(archive,first),"same id different body cannot replace archived request");
        check(FeedbackDraftStore.load(archive,id).getString("body").equals("uncertain body"),"history returns original body with original request id");check(FeedbackDraftStore.recent(archive,20).items.size()==2,"history exposes preserved requests independently from current editor");fails(()->FeedbackDraftStore.read(archive,"../outside"),"history cannot read a path as a request id");fails(()->FeedbackDraftStore.recent(archive,21),"history response is bounded to twenty");
        String alteredId="cccccccccccccccccccccccccccccccc";JSONObject altered=FeedbackClient.payload(alteredId,"bug","bad","body","",false,"0.5.0","android");altered.put("notePaths","must not be sent");java.nio.file.Files.write(new java.io.File(archive,alteredId+".json").toPath(),altered.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));fails(()->FeedbackDraftStore.read(archive,alteredId),"unknown archived fields cannot be sent");
        altered.remove("notePaths");altered.put("schema","1");java.nio.file.Files.write(new java.io.File(archive,alteredId+".json").toPath(),altered.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));fails(()->FeedbackDraftStore.read(archive,alteredId),"archive schema types are strict");
        String hugeId="dddddddddddddddddddddddddddddddd";java.nio.file.Files.write(new java.io.File(archive,hugeId+".json").toPath(),new byte[FeedbackClient.MAX_BYTES+1]);fails(()->FeedbackDraftStore.read(archive,hugeId),"oversized archive cannot allocate unbounded content");check(FeedbackDraftStore.recent(archive,20).skipped==2,"bad records retained and reported separately");
        for(int n=1;n<=22;n++){String otherId=String.format(java.util.Locale.ROOT,"%032x",n);FeedbackDraftStore.preserve(archive,FeedbackClient.payload(otherId,"suggestion","entry "+n,"body","",false,"0.5.0","android"));java.nio.file.Files.setLastModifiedTime(new java.io.File(archive,otherId+".json").toPath(),java.nio.file.attribute.FileTime.fromMillis(4102444800000L+n));}
        FeedbackDraftStore.Recent recent=FeedbackDraftStore.recent(archive,20);check(recent.items.size()==20,"history list remains bounded with many records");check(recent.items.get(0).id.equals(String.format(java.util.Locale.ROOT,"%032x",22)),"history sorts latest attempts first");
        System.out.println("Settings and feedback checks passed: "+passed);
    }
}
